import{_ as i,C as r,o as s,c as l,a2 as t,j as n,a as e,E as d}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"KomaYomi — Manga Learner documentation","titleTemplate":false,"description":"KomaYomi (Manga Learner) documentation — learn languages with manga, compare Japanese, Chinese and English pages, detect panels, align artwork and take notes.","frontmatter":{"layout":"home","titleTemplate":false,"description":"KomaYomi (Manga Learner) documentation — learn languages with manga, compare Japanese, Chinese and English pages, detect panels, align artwork and take notes.","title":"KomaYomi — Manga Learner documentation","hero":{"name":"KomaYomi","text":"Manga Learner","tagline":"Learn languages with manga, take notes. Panels, comparison and notes stay on your own machine.","image":{"src":"/assets/screenshots/hero-real-library.png","alt":"Compare reader with three language panes from a real library; the manga artwork is blurred"},"actions":[{"theme":"brand","text":"Get started","link":"/guide/introduction"},{"theme":"alt","text":"Data formats","link":"/data-format"}]},"features":[{"title":"Panels first","details":"Automatic XY-cut detection with manual drawing, merging, numbering and reusable layout templates. Old annotations are remapped when panel counts match."},{"title":"Compare up to three languages","details":"Side-by-side or overlay views, per-language masks, wheel zoom and pan, plus page / panel / anchor / grid alignment with reusable presets."},{"title":"Notes that travel","details":"Markdown notes at page or panel scope, tags, sources, a scratch pad, full-text search and one-click \\"copy context\\" for pasting into an LLM."},{"title":"Portable output","details":"Export HTML with an image folder or as a single embedded file, render page / panel / collage PNGs, and move everything as a `.mnproj` project."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1794747607000}'),m={name:"index.md"};function p(g,a,c,u,h,f){const o=r("Badge");return s(),l("div",null,[a[4]||(a[4]=t('<h2 id="what-is-komayomi" tabindex="-1">What is KomaYomi? <a class="header-anchor" href="#what-is-komayomi" aria-label="Permalink to &quot;What is KomaYomi?&quot;">​</a></h2><p>KomaYomi — <strong>Manga Learner</strong> — is a <strong>local web application</strong> for learning languages with manga: read the same pages in Japanese, Chinese and English, align them closely, and take notes. Your page images stay in a <code>raw/</code> folder; every panel, note, tag, alignment offset and annotation lives in plain JSON under <code>data/</code>. Nothing leaves the machine unless you export it.</p><p>It is designed for study and translation review rather than for hosting copyrighted material: bring your own scans, point the app at the folder, and work page by page.</p><h2 id="status-at-a-glance" tabindex="-1">Status at a glance <a class="header-anchor" href="#status-at-a-glance" aria-label="Permalink to &quot;Status at a glance&quot;">​</a></h2><p>KomaYomi is at <strong>0.1.0 and under active development</strong>. The documentation distinguishes what exists today from what is planned.</p><div class="status-list"><div><strong>Working today</strong> — library scanning, XY-cut panel detection, manual panel editing, panel/layout templates, vector annotations (rectangle, ellipse, arrow, text), compare reader with masks and four alignment modes, Markdown notes with search, HTML and PNG export, backup ZIP plus upload to a WebDAV/network target, a WebDAV/network image source with on-demand LRU caching, `.mnproj` project export/import, CLI batch tools.</div><div><strong>Planned</strong> — in-app panel-group editing; PDF, Word (docx) and vocabulary-list export; an offline write queue; scheduled backups; a native mobile app; broader integration tests.</div></div>',6)),n("p",null,[a[0]||(a[0]=e("Anything marked ",-1)),d(o,{type:"warning",text:"Planned"}),a[1]||(a[1]=e(" in this site is ",-1)),a[2]||(a[2]=n("strong",null,"not implemented yet",-1)),a[3]||(a[3]=e(". If a page describes behavior that is not in the code, treat this note as authoritative and the feature as unavailable.",-1))]),a[5]||(a[5]=t('<h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>New here? Read <a href="/KomaYomi-docs/guide/introduction">Introduction</a>, then <a href="/KomaYomi-docs/guide/installation">Install &amp; Run</a>.</li><li>Want the mental model? Start with <a href="/KomaYomi-docs/concepts">Core Concepts</a>.</li><li>Building on the JSON or writing a plugin? Go to <a href="/KomaYomi-docs/data-format">Data Formats</a> and <a href="/KomaYomi-docs/extending">Layout Templates &amp; Plugins</a>.</li><li>Stuck on a missing page or a broken export? See <a href="/KomaYomi-docs/faq">FAQ &amp; Troubleshooting</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Documentation languages</p><p>English is the primary language. A Chinese translation lives under <code>/zh/</code> and a Japanese one under <code>/ja/</code>. Each page states its status separately.</p></div>',3))])}const k=i(m,[["render",p]]);export{b as __pageData,k as default};
